import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
cells = {}
vals = {}
for i in range(r):
    for j in range(c):
        v = int(data[2 + i * c + j])
        if v:
            cells[(i, j)] = len(cells)
            vals[(i, j)] = v
INF = 10**9
m = len(cells)
D = [[INF] * m for _ in range(m)]
for (i, j), a in cells.items():
    D[a][a] = 0
    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        b = cells.get((i + di, j + dj))
        if b is not None:
            D[a][b] = 1
for k in range(m):
    for a in range(m):
        for b in range(m):
            if D[a][k] + D[k][b] < D[a][b]:
                D[a][b] = D[a][k] + D[k][b]
trees = sorted((v, p) for p, v in vals.items() if v > 1)
cur = cells[(0, 0)]
total = 0
ok = True
for v, p in trees:
    t = cells[p]
    if D[cur][t] >= INF:
        ok = False
        break
    total += D[cur][t]
    cur = t
print(total if ok else -1)

